import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv_transpose2d(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
    int64_t stride_h, int64_t stride_w,
    int64_t pad_h, int64_t pad_w,
    int64_t dil_h, int64_t dil_w,
    int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ out_ptr,
    int N, int C_in, int H_in, int W_in,
    int C_out, int H_out, int W_out,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups)
{
    int in_channels_per_group  = C_in / groups;
    int out_channels_per_group = C_out / groups;

    int n = blockIdx.z / groups;
    int g = blockIdx.z % groups;

    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int ow = blockIdx.x * blockDim.x + threadIdx.x;

    // Cooperative load of this group's weight slice into shared memory
    extern __shared__ float smem[];
    int weight_group_size = in_channels_per_group * out_channels_per_group * KH * KW;
    const float* w_group_ptr = w_ptr + (size_t)g * (size_t)weight_group_size;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y;
    for (int idx = tid; idx < weight_group_size; idx += nthreads) {
        smem[idx] = w_group_ptr[idx];
    }
    __syncthreads();

    if (n >= N || oh >= H_out || ow >= W_out) return;

    // CuTe tensor views over global memory
    Tensor gX = make_tensor(make_gmem_ptr(x_ptr),
                             make_shape(N, C_in, H_in, W_in),
                             make_stride(C_in * H_in * W_in, H_in * W_in, W_in, 1));

    Tensor gOut = make_tensor(make_gmem_ptr(out_ptr),
                               make_shape(N, C_out, H_out, W_out),
                               make_stride(C_out * H_out * W_out, H_out * W_out, W_out, 1));

    // CuTe tensor view over shared memory weight slice for this group
    Tensor sW = make_tensor(make_smem_ptr(smem),
                             make_shape(in_channels_per_group, out_channels_per_group, KH, KW),
                             make_stride(out_channels_per_group * KH * KW, KH * KW, KW, 1));

    for (int oc_local = 0; oc_local < out_channels_per_group; ++oc_local) {
        float acc = 0.f;
        if (bias_ptr != nullptr) {
            acc = bias_ptr[g * out_channels_per_group + oc_local];
        }
        for (int kh = 0; kh < KH; ++kh) {
            int t_h = oh + pad_h - kh * dil_h;
            if (t_h % stride_h != 0) continue;
            int ih = t_h / stride_h;
            if (ih < 0 || ih >= H_in) continue;
            for (int kw = 0; kw < KW; ++kw) {
                int t_w = ow + pad_w - kw * dil_w;
                if (t_w % stride_w != 0) continue;
                int iw = t_w / stride_w;
                if (iw < 0 || iw >= W_in) continue;
                for (int ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
                    int ic = g * in_channels_per_group + ic_local;
                    acc += gX(n, ic, ih, iw) * sW(ic_local, oc_local, kh, kw);
                }
            }
        }
        int oc = g * out_channels_per_group + oc_local;
        gOut(n, oc, oh, ow) = acc;
    }
}

torch::Tensor cute_conv_transpose2d(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
    int64_t stride_h, int64_t stride_w,
    int64_t pad_h, int64_t pad_w,
    int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D (C_in, C_out/groups, KH, KW)");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int N    = (int)x_c.size(0);
    int C_in = (int)x_c.size(1);
    int H_in = (int)x_c.size(2);
    int W_in = (int)x_c.size(3);

    int out_channels_per_group = (int)w_c.size(1);
    int KH = (int)w_c.size(2);
    int KW = (int)w_c.size(3);
    int groups_i = (int)groups;
    int C_out = out_channels_per_group * groups_i;

    int H_out = (H_in - 1) * (int)stride_h - 2 * (int)pad_h + (int)dil_h * (KH - 1) + 1;
    int W_out = (W_in - 1) * (int)stride_w - 2 * (int)pad_w + (int)dil_w * (KW - 1) + 1;

    auto out = torch::zeros({N, C_out, H_out, W_out}, x.options());

    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (bias.defined() && bias.numel() > 0) {
        bias_c = bias.contiguous();
        TORCH_CHECK(bias_c.scalar_type() == at::kFloat, "bias must be float32");
        bias_ptr = bias_c.data_ptr<float>();
    }

    int in_channels_per_group = C_in / groups_i;
    int weight_group_size = in_channels_per_group * out_channels_per_group * KH * KW;
    size_t smem_bytes = (size_t)weight_group_size * sizeof(float);

    dim3 block(16, 16);
    dim3 grid((W_out + block.x - 1) / block.x,
              (H_out + block.y - 1) / block.y,
              (unsigned)(N * groups_i));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    conv_transpose2d_kernel<<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, out.data_ptr<float>(),
        N, C_in, H_in, W_in, C_out, H_out, W_out,
        KH, KW,
        (int)stride_h, (int)stride_w,
        (int)pad_h, (int)pad_w,
        (int)dil_h, (int)dil_w,
        groups_i);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv_transpose2d launch failed");
    return out;
}
"""

cute_ext = load_inline(
    name="cute_conv_transpose2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv_transpose2d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a 2D transposed convolution using a custom fused CuTe/CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.ConvTranspose2d purely to hold/initialize the parameters
        # (weight, bias) in the exact same way as the reference model.
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, dilation=dilation,
            groups=groups, bias=bias
        )
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose2d.weight
        bias = self.conv_transpose2d.bias
        if bias is None:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)
        return self._ext.cute_conv_transpose2d(
            x, weight, bias,
            self.stride[0], self.stride[1],
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1],
            self.groups
        )

